import{printedArtwork}from'../../modeling/artwork.js';import{spec}from'./dimensions.js';const sources={front:new URL('./reference-redraw-front.png',import.meta.url).href,back:new URL('./reference-redraw-back.png',import.meta.url).href};export function addStickers(host){const result=[];for(const face of Object.keys(host.lorawanCn470Assembly.labels)){const v=spec.labels[face],position=[...v.position];if(face==='front')position[2]+=.08;result.push(...printedArtwork(host,{target:host.lorawanCn470Assembly.labels[face],url:sources[face],size:v.size,position,face,depth:.12,name:'LoRaWAN-CN470 own U184-CN470 '+face+' source raster',artworkKind:'reference-redraw-raster'})??[]);}return result;}
